UPDATE `#__guidedtours` SET `autostart` = 0;
INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Locking an Article', 'joomlaguide-locking-an-article', '<p>When someone edits an article, Joomla <em>checks it out</em>: it is locked, so nobody else can change it at the same time. Saving or closing the article <em>checks it in</em> again.</p><p>If the editor leaves without saving or closing, the article stays locked. In this tour you see how that happens and how an administrator unlocks it.</p><p>This tour follows the tutorial <a href="https://guide.joomla.org/tutorials/content-management/publishing-and-access-restrictions/locking-an-article" target="_blank" rel="noopener">7.5 Locking an Article</a> of the Joomla User Guide.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 7.5 Locking an Article', 1, 1);
INSERT INTO `#__guidedtour_steps` (`tour_id`, `title`, `description`, `ordering`, `position`, `target`, `type`, `interactive_type`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `params`) VALUES
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Content', '<p>In the menu on the left, click <strong>Content</strong>.</p><p>It opens and shows what you can do there.</p>', 1, 'right', 'body.com_cpanel #sidebarmenu li.item-level-1:has(a[href="index.php?option=com_content&view=articles"]) > a.has-arrow', 2, 4, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Content › Articles', '<p>Click <strong>Articles</strong> in <strong>Content</strong>.</p>', 2, 'right', 'body.com_cpanel #sidebarmenu a[href="index.php?option=com_content&view=articles"]', 2, 1, 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Open the article', '<p>Click <strong>City Council Approves New Transit Budget</strong> to edit it.</p>', 3, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" City Council Approves New Transit Budget"]) a[href*="task=article.edit"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Leave without closing', '<p>You are editing the article now. Do not click <strong>Save</strong> or <strong>Close</strong>: press the <em>Back</em> button of your browser. This is what an editor does who leaves without closing.</p><p>Back in the list, the article has a lock: it is checked out. Hover over the lock to see who checked it out, and when. (No lock? Reload the page.)</p>', 4, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" City Council Approves New Transit Budget"]) th', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Who can edit it?', '<p>You checked the article out, so you can still open it. Other users, even administrators, get an error message when they try.</p><p>When you click <strong>Close</strong> or <strong>Save & Close</strong> in the article, it is checked in again.</p>', 5, 'bottom', '#articleList tr:has(a[href*="task=article.edit"][title$=" City Council Approves New Transit Budget"])', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Check the article in', '<p>Here the editor did not come back. As an administrator you can unlock the article: click the lock.</p>', 6, 'right', '#articleList tr:has(a[href*="task=article.edit"][title$=" City Council Approves New Transit Budget"]) [data-item-task="articles.checkin"]', 2, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL),
((SELECT `id` FROM `#__guidedtours` WHERE `uid` = 'joomlaguide-locking-an-article'), 'Well done!', '<p>The article is checked in, and anyone with permission can edit it again.</p><p>To check in many articles at once, tick their checkboxes and choose <strong>Actions</strong> › <strong>Check-in</strong>.</p><p>Take care: if the editor is still working on the article, their changes may be lost.</p>', 7, 'bottom', '#system-message-container', 0, 1, 'administrator/index.php?option=com_content&view=articles', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', '', NULL);
